   200→/// TC-INP-003: Verify consistent coordinate system convention (OpenCV/COLMAP vs OpenGL).
   201→///
   202→/// Pass Criteria:
   203→/// - Projected coordinates match analytical solution within 1e-4
   204→/// - Coordinate system documented and verified
   205→///
   206→/// This test verifies that we use a consistent coordinate system throughout the pipeline:
   207→/// - Camera space: +Z forward (into scene), +X right, +Y down (OpenCV/COLMAP convention)
   208→/// - World to camera: p_cam = R * p_world + t
   209→/// - Projection: [u, v] = [fx * x/z + cx, fy * y/z + cy]
   210→#[test]
   211→fn tc_inp_003_coordinate_system_convention() {
   212→    const TOLERANCE: f32 = 1e-4; // Tolerance for floating-point comparisons
   213→    use nalgebra::{Matrix3, Quaternion, UnitQuaternion, Vector3};
   214→    use sugar_rs::core::Camera;
   215→
   216→    println!("\n=== TC-INP-003: Coordinate System Convention Verification ===\n");
   217→
   218→    // Test Case 1: Identity camera, simple point
   219→    // Camera at origin, looking down +Z axis
   220→    {
   221→        let camera = Camera::new(
   222→            100.0,               // fx
   223→            100.0,               // fy
   224→            50.0,                // cx
   225→            50.0,                // cy
   226→            100,                 // width
   227→            100,                 // height
   228→            Matrix3::identity(), // rotation (identity = no rotation)
   229→            Vector3::zeros(),    // translation (at origin)
   230→        );
   231→
   232→        // Point at (1, 2, 5) in world space
   233→        // With identity camera, world = camera space
   234→        // Expected projection: u = 100 * (1/5) + 50 = 70
   235→        //                      v = 100 * (2/5) + 50 = 90
   236→        let point_world = Vector3::new(1.0, 2.0, 5.0);
   237→        let expected_pixel = Vector3::new(70.0, 90.0, 5.0); // [u, v, depth]
   238→
   239→        let pixel = camera.world_to_pixel(&point_world)
   240→            .expect("Point should be in front of camera");
   241→
   242→        println!("Test 1 - Identity camera:");
   243→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   244→        println!("  Expected pixel: ({:.6}, {:.6})", expected_pixel.x, expected_pixel.y);
   245→        println!("  Computed pixel: ({:.6}, {:.6})", pixel.x, pixel.y);
   246→        println!("  Error: ({:.6}, {:.6})",
   247→            (pixel.x - expected_pixel.x).abs(),
   248→            (pixel.y - expected_pixel.y).abs());
   249→
   250→        assert!((pixel.x - expected_pixel.x).abs() < TOLERANCE,
   251→            "X projection error too large: {} vs {}", pixel.x, expected_pixel.x);
   252→        assert!((pixel.y - expected_pixel.y).abs() < TOLERANCE,
   253→            "Y projection error too large: {} vs {}", pixel.y, expected_pixel.y);
   254→
   255→        println!("  ✓ Identity camera projection correct\n");
   256→    }
   257→
   258→    // Test Case 2: Translated camera
   259→    // Camera translated to (10, 0, 0), still looking down +Z
   260→    {
   261→        let camera = Camera::new(
   262→            100.0,
   263→            100.0,
   264→            50.0,
   265→            50.0,
   266→            100,
   267→            100,
   268→            Matrix3::identity(),
   269→            Vector3::new(10.0, 0.0, 0.0), // translation
   270→        );
   271→
   272→        // Point at (11, 2, 5) in world space
   273→        // In camera space: p_cam = I * (11, 2, 5) + (10, 0, 0) = (21, 2, 5)
   274→        // Expected projection: u = 100 * (21/5) + 50 = 470
   275→        //                      v = 100 * (2/5) + 50 = 90
   276→        let point_world = Vector3::new(11.0, 2.0, 5.0);
   277→        let expected_pixel = Vector3::new(470.0, 90.0, 5.0);
   278→
   279→        let pixel = camera.world_to_pixel(&point_world)
   280→            .expect("Point should be in front of camera");
   281→
   282→        println!("Test 2 - Translated camera:");
   283→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   284→        println!("  Expected pixel: ({:.6}, {:.6})", expected_pixel.x, expected_pixel.y);
   285→        println!("  Computed pixel: ({:.6}, {:.6})", pixel.x, pixel.y);
   286→        println!("  Error: ({:.6}, {:.6})",
   287→            (pixel.x - expected_pixel.x).abs(),
   288→            (pixel.y - expected_pixel.y).abs());
   289→
   290→        assert!((pixel.x - expected_pixel.x).abs() < TOLERANCE,
   291→            "X projection error too large: {} vs {}", pixel.x, expected_pixel.x);
   292→        assert!((pixel.y - expected_pixel.y).abs() < TOLERANCE,
   293→            "Y projection error too large: {} vs {}", pixel.y, expected_pixel.y);
   294→
   295→        println!("  ✓ Translated camera projection correct\n");
   296→    }
   297→
   298→    // Test Case 3: Rotated camera (90° rotation around Y-axis)
   299→    // Camera rotated 90° around Y-axis: was looking at +Z, now looking at +X
   300→    {
   301→        // Rotation by 90° around Y-axis (counter-clockwise when looking down -Y)
   302→        // This rotates +Z to +X
   303→        let angle = std::f32::consts::FRAC_PI_2; // 90 degrees
   304→        let axis = Vector3::y_axis();
   305→        let rotation_quat = UnitQuaternion::from_axis_angle(&axis, angle);
   306→        let rotation_matrix = rotation_quat.to_rotation_matrix().into_inner();
   307→
   308→        let camera = Camera::new(
   309→            100.0,
   310→            100.0,
   311→            50.0,
   312→            50.0,
   313→            100,
   314→            100,
   315→            rotation_matrix,
   316→            Vector3::zeros(),
   317→        );
   318→
   319→        // Point at (5, 2, 1) in world space
   320→        // After 90° rotation around Y: (x,y,z) -> (z, y, -x)
   321→        // In camera space: R * (5, 2, 1) = (1, 2, -5)
   322→        // Depth check: z = -5, which is negative (behind camera)
   323→        // So this point should NOT project
   324→
   325→        // Let's use a point that will be in front
   326→        // Point at (5, 2, -1) in world space
   327→        // After rotation: R * (5, 2, -1) = (-1, 2, -5) - still behind
   328→
   329→        // For a point to be in front after Y-rotation by 90°:
   330→        // We need R * p to have positive z
   331→        // R_y(90°) maps (x,y,z) -> (z, y, -x)
   332→        // For positive z in camera: -x > 0, so x < 0 in world
   333→
   334→        let point_world = Vector3::new(-5.0, 2.0, 1.0);
   335→        // After rotation: (-5, 2, 1) -> (1, 2, 5) in camera space
   336→        // Expected projection: u = 100 * (1/5) + 50 = 70
   337→        //                      v = 100 * (2/5) + 50 = 90
   338→        let expected_pixel = Vector3::new(70.0, 90.0, 5.0);
   339→
   340→        let pixel = camera.world_to_pixel(&point_world)
   341→            .expect("Point should be in front of camera");
   342→
   343→        println!("Test 3 - Rotated camera (90° around Y):");
   344→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   345→        println!("  Expected pixel: ({:.6}, {:.6})", expected_pixel.x, expected_pixel.y);
   346→        println!("  Computed pixel: ({:.6}, {:.6})", pixel.x, pixel.y);
   347→        println!("  Error: ({:.6}, {:.6})",
   348→            (pixel.x - expected_pixel.x).abs(),
   349→            (pixel.y - expected_pixel.y).abs());
   350→
   351→        assert!((pixel.x - expected_pixel.x).abs() < TOLERANCE,
   352→            "X projection error too large: {} vs {}", pixel.x, expected_pixel.x);
   353→        assert!((pixel.y - expected_pixel.y).abs() < TOLERANCE,
   354→            "Y projection error too large: {} vs {}", pixel.y, expected_pixel.y);
   355→
   356→        println!("  ✓ Rotated camera projection correct\n");
   357→    }
   358→
   359→    // Test Case 4: General camera pose (combined rotation and translation)
   360→    {
   361→        // 45° rotation around Y-axis
   362→        let angle = std::f32::consts::FRAC_PI_4; // 45 degrees
   363→        let axis = Vector3::y_axis();
   364→        let rotation_quat = UnitQuaternion::from_axis_angle(&axis, angle);
   365→        let rotation_matrix = rotation_quat.to_rotation_matrix().into_inner();
   366→
   367→        let translation = Vector3::new(1.0, 2.0, 3.0);
   368→
   369→        let camera = Camera::new(
   370→            200.0, // fx
   371→            200.0, // fy
   372→            100.0, // cx
   373→            100.0, // cy
   374→            200,
   375→            200,
   376→            rotation_matrix,
   377→            translation,
   378→        );
   379→
   380→        // Point at (5, 3, 8) in world space
   381→        let point_world = Vector3::new(5.0, 3.0, 8.0);
   382→
   383→        // Manually compute expected projection
   384→        // p_cam = R * p_world + t
   385→        let point_camera = rotation_matrix * point_world + translation;
   386→
   387→        // Should have positive z (in front)
   388→        assert!(point_camera.z > 0.0,
   389→            "Test point should be in front of camera, got z={}", point_camera.z);
   390→
   391→        // Expected projection: [u, v] = [fx * x/z + cx, fy * y/z + cy]
   392→        let expected_u = 200.0 * point_camera.x / point_camera.z + 100.0;
   393→        let expected_v = 200.0 * point_camera.y / point_camera.z + 100.0;
   394→        let expected_pixel = Vector3::new(expected_u, expected_v, point_camera.z);
   395→
   396→        let pixel = camera.world_to_pixel(&point_world)
   397→            .expect("Point should be in front of camera");
   398→
   399→        println!("Test 4 - General camera pose:");
   400→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   401→        println!("  Camera point: ({:.6}, {:.6}, {:.6})", point_camera.x, point_camera.y, point_camera.z);
   402→        println!("  Expected pixel: ({:.6}, {:.6})", expected_pixel.x, expected_pixel.y);
   403→        println!("  Computed pixel: ({:.6}, {:.6})", pixel.x, pixel.y);
   404→        println!("  Error: ({:.6}, {:.6})",
   405→            (pixel.x - expected_pixel.x).abs(),
   406→            (pixel.y - expected_pixel.y).abs());
   407→
   408→        assert!((pixel.x - expected_pixel.x).abs() < TOLERANCE,
   409→            "X projection error too large: {} vs {}", pixel.x, expected_pixel.x);
   410→        assert!((pixel.y - expected_pixel.y).abs() < TOLERANCE,
   411→            "Y projection error too large: {} vs {}", pixel.y, expected_pixel.y);
   412→
   413→        println!("  ✓ General camera projection correct\n");
   414→    }
   415→
   416→    // Test Case 5: Verify point behind camera is rejected
   417→    {
   418→        let camera = Camera::new(
   419→            100.0,
   420→            100.0,
   421→            50.0,
   422→            50.0,
   423→            100,
   424→            100,
   425→            Matrix3::identity(),
   426→            Vector3::zeros(),
   427→        );
   428→
   429→        // Point with negative Z (behind camera)
   430→        let point_world = Vector3::new(1.0, 2.0, -5.0);
   431→        let pixel = camera.world_to_pixel(&point_world);
   432→
   433→        println!("Test 5 - Point behind camera:");
   434→        println!("  World point: ({:.6}, {:.6}, {:.6})", point_world.x, point_world.y, point_world.z);
   435→        println!("  Projection result: {:?}", pixel);
   436→
   437→        assert!(pixel.is_none(),
   438→            "Point behind camera should not project");
   439→
   440→        println!("  ✓ Point behind camera correctly rejected\n");
   441→    }
   442→
   443→    println!("✅ TC-INP-003: Coordinate system convention verified");
   444→    println!("   Convention: OpenCV/COLMAP (Z-forward, camera-to-world)");
   445→    println!("   World to camera: p_cam = R * p_world + t");
   446→    println!("   Projection: [u,v] = [fx*x/z + cx, fy*y/z + cy]");
   447→    println!("   All analytical projections match within {}", TOLERANCE);
   448→}
