   450→/// TC-INP-010: Verify 3D points correctly loaded from COLMAP sparse reconstruction.
   451→///
   452→/// Pass Criteria:
   453→/// - Point count matches source file
   454→/// - Point positions within 1e-5 of source values
   455→/// - Visual alignment with input images (manual check)
   456→#[test]
   457→fn tc_inp_010_colmap_point_cloud_loading() {
   458→    use byteorder::{LittleEndian, ReadBytesExt};
   459→    use std::fs::File;
   460→    use std::io::BufReader;
   461→
   462→    // Use a known dataset
   463→    let dataset_path = PathBuf::from("datasets/garden/sparse/0");
   464→
   465→    if !dataset_path.exists() {
   466→        eprintln!("Skipping test - dataset not found at {:?}", dataset_path);
   467→        eprintln!("Run setup to download datasets first");
   468→        return;
   469→    }
   470→
   471→    // Load the scene using our implementation
   472→    let scene = load_colmap_scene(&dataset_path)
   473→        .expect("Failed to load COLMAP scene");
   474→
   475→    println!("Loaded {} 3D points from COLMAP scene", scene.points.len());
   476→
   477→    // Read the points3D.bin file directly for ground truth comparison
   478→    let points_path = dataset_path.join("points3D.bin");
   479→    let file = File::open(&points_path).expect("Failed to open points3D.bin");
   480→    let mut reader = BufReader::new(file);
   481→
   482→    // Read number of points from binary file
   483→    let num_points = reader.read_u64::<LittleEndian>().expect("Failed to read num_points");
   484→
   485→    println!("Ground truth file contains {} points", num_points);
   486→
   487→    // Verify point count matches
   488→    assert_eq!(
   489→        scene.points.len(),
   490→        num_points as usize,
   491→        "Point count mismatch: loaded {} points, but file contains {}",
   492→        scene.points.len(),
   493→        num_points
   494→    );
   495→
   496→    // Verify precision of point positions by comparing against ground truth
   497→    let mut max_position_error = 0.0_f32;
   498→    let mut max_color_diff = 0_u8;
   499→    let mut num_precision_checks = 0;
   500→
   501→    for i in 0..num_points as usize {
   502→        // Read ground truth from binary file
   503→        let gt_point_id = reader.read_u64::<LittleEndian>().expect("Failed to read point_id");
   504→        let gt_x = reader.read_f64::<LittleEndian>().expect("Failed to read x") as f32;
   505→        let gt_y = reader.read_f64::<LittleEndian>().expect("Failed to read y") as f32;
   506→        let gt_z = reader.read_f64::<LittleEndian>().expect("Failed to read z") as f32;
   507→        let gt_r = reader.read_u8().expect("Failed to read r");
   508→        let gt_g = reader.read_u8().expect("Failed to read g");
   509→        let gt_b = reader.read_u8().expect("Failed to read b");
   510→        let gt_error = reader.read_f64::<LittleEndian>().expect("Failed to read error") as f32;
   511→
   512→        // Skip track data
   513→        let track_length = reader.read_u64::<LittleEndian>().expect("Failed to read track_length");
   514→        for _ in 0..track_length {
   515→            reader.read_u32::<LittleEndian>().expect("Failed to skip image_id");
   516→            reader.read_u32::<LittleEndian>().expect("Failed to skip point2d_idx");
   517→        }
   518→
   519→        // Find corresponding point in loaded scene (by ID)
   520→        let loaded_point = scene.points.iter()
   521→            .find(|p| p.id == gt_point_id)
   522→            .expect(&format!("Point ID {} not found in loaded scene", gt_point_id));
   523→
   524→        // Check position precision
   525→        let pos_error_x = (loaded_point.position.x - gt_x).abs();
   526→        let pos_error_y = (loaded_point.position.y - gt_y).abs();
   527→        let pos_error_z = (loaded_point.position.z - gt_z).abs();
   528→        let pos_error = pos_error_x.max(pos_error_y).max(pos_error_z);
   529→
   530→        max_position_error = max_position_error.max(pos_error);
   531→
   532→        // Check color matches exactly
   533→        let color_diff_r = (loaded_point.color[0] as i16 - gt_r as i16).abs() as u8;
   534→        let color_diff_g = (loaded_point.color[1] as i16 - gt_g as i16).abs() as u8;
   535→        let color_diff_b = (loaded_point.color[2] as i16 - gt_b as i16).abs() as u8;
   536→        max_color_diff = max_color_diff.max(color_diff_r).max(color_diff_g).max(color_diff_b);
   537→
   538→        // Check reprojection error precision
   539→        let error_diff = (loaded_point.error - gt_error).abs();
   540→
   541→        // Print details for first few points
   542→        if i < 3 {
   543→            println!("\nPoint {} (ID {}):", i, gt_point_id);
   544→            println!("  Position GT:     ({:.6}, {:.6}, {:.6})", gt_x, gt_y, gt_z);
